* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  background: #1a1a2e;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  padding: 16px;
}

.game-container {
  background: #16213e;
  border-radius: 16px;
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

.title {
  color: #e94560;
  font-size: 28px;
  letter-spacing: 2px;
  text-transform: uppercase;
  text-shadow: 2px 2px 0 #0f3460;
}

.game-board {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  width: 100%;
}

.hangman-drawing {
  position: relative;
  width: 200px;
  height: 220px;
  background: #0f3460;
  border-radius: 8px;
  overflow: hidden;
}

/* Gallows */
.gallows {
  position: absolute;
  bottom: 0;
  left: 20px;
  width: 160px;
  height: 10px;
  background: #533483;
}
.gallows::before {
  content: '';
  position: absolute;
  bottom: 0;
  left: 70px;
  width: 10px;
  height: 200px;
  background: #533483;
}
.gallows::after {
  content: '';
  position: absolute;
  top: 0;
  left: 70px;
  width: 80px;
  height: 10px;
  background: #533483;
}

/* Body parts (hidden initially) */
.head, .body, .left-arm, .right-arm, .left-leg, .right-leg {
  position: absolute;
  background: #e94560;
  opacity: 0;
  transition: opacity 0.3s;
}

.head {
  top: 10px;
  left: 140px;
  width: 40px;
  height: 40px;
  border-radius: 50%;
}
.body {
  top: 50px;
  left: 155px;
  width: 10px;
  height: 60px;
}
.left-arm {
  top: 60px;
  left: 130px;
  width: 30px;
  height: 8px;
  transform: rotate(-30deg);
}
.right-arm {
  top: 60px;
  left: 155px;
  width: 30px;
  height: 8px;
  transform: rotate(30deg);
}
.left-leg {
  top: 110px;
  left: 135px;
  width: 30px;
  height: 8px;
  transform: rotate(30deg);
}
.right-leg {
  top: 110px;
  left: 155px;
  width: 30px;
  height: 8px;
  transform: rotate(-30deg);
}

/* Show body parts based on wrong guesses */
.hangman-drawing[data-wrong="1"] .head { opacity: 1; }
.hangman-drawing[data-wrong="2"] .body { opacity: 1; }
.hangman-drawing[data-wrong="3"] .left-arm { opacity: 1; }
.hangman-drawing[data-wrong="4"] .right-arm { opacity: 1; }
.hangman-drawing[data-wrong="5"] .left-leg { opacity: 1; }
.hangman-drawing[data-wrong="6"] .right-leg { opacity: 1; }

.word-display {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
  font-size: 32px;
  font-weight: bold;
  color: #e0e0e0;
  letter-spacing: 4px;
  min-height: 48px;
}

.word-display span {
  display: inline-block;
  min-width: 24px;
  text-align: center;
  border-bottom: 3px solid #533483;
  padding-bottom: 4px;
}

.wrong-guesses {
  color: #a0a0b0;
  font-size: 16px;
}

.keyboard {
  display: grid;
  grid-template-columns: repeat(9, 1fr);
  gap: 6px;
  width: 100%;
}

.keyboard button {
  background: #0f3460;
  color: #e0e0e0;
  border: 2px solid #533483;
  border-radius: 6px;
  padding: 10px 0;
  font-size: 18px;
  font-weight: bold;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  min-height: 44px;
}

.keyboard button:hover:not(:disabled) {
  background: #533483;
  border-color: #e94560;
}

.keyboard button:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}

.keyboard button:active:not(:disabled) {
  transform: scale(0.95);
}

.keyboard button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  background: #1a1a2e;
}

.message {
  font-size: 20px;
  font-weight: bold;
  min-height: 28px;
  text-align: center;
}

.message.win {
  color: #4ecca3;
}

.message.lose {
  color: #e94560;
}

.new-game-btn {
  background: #e94560;
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 14px 32px;
  font-size: 18px;
  font-weight: bold;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  min-height: 48px;
}

.new-game-btn:hover {
  background: #c73650;
}

.new-game-btn:focus-visible {
  outline: 3px solid #e0e0e0;
  outline-offset: 2px;
}

.new-game-btn:active {
  transform: scale(0.97);
}

@media (max-width: 480px) {
  .game-container {
    padding: 16px;
    gap: 16px;
  }
  .title {
    font-size: 22px;
  }
  .hangman-drawing {
    width: 160px;
    height: 180px;
  }
  .gallows {
    left: 10px;
    width: 140px;
  }
  .gallows::before {
    left: 60px;
    height: 160px;
  }
  .gallows::after {
    left: 60px;
    width: 70px;
  }
  .head {
    top: 8px;
    left: 120px;
    width: 32px;
    height: 32px;
  }
  .body {
    top: 40px;
    left: 131px;
    height: 50px;
  }
  .left-arm {
    top: 50px;
    left: 110px;
  }
  .right-arm {
    top: 50px;
    left: 131px;
  }
  .left-leg {
    top: 90px;
    left: 115px;
  }
  .right-leg {
    top: 90px;
    left: 131px;
  }
  .word-display {
    font-size: 24px;
    gap: 6px;
  }
  .keyboard {
    gap: 4px;
  }
  .keyboard button {
    font-size: 16px;
    padding: 8px 0;
    min-height: 40px;
  }
  .new-game-btn {
    padding: 12px 24px;
    font-size: 16px;
  }
}

const WORDS = ['JAVASCRIPT', 'HANGMAN', 'PIXEL', 'GAME', 'DEVELOPER', 'BROWSER', 'KEYBOARD', 'CANVAS', 'STYLE', 'LOGIC'];
const MAX_WRONG = 6;

let currentWord = '';
let guessedLetters = new Set();
let wrongCount = 0;
let gameOver = false;

const wordDisplay = document.getElementById('word-display');
const wrongGuessesDisplay = document.getElementById('wrong-guesses');
const messageEl = document.getElementById('message');
const keyboardEl = document.getElementById('keyboard');
const hangmanDrawing = document.querySelector('.hangman-drawing');
const newGameBtn = document.getElementById('new-game');

function initKeyboard() {
  keyboardEl.innerHTML = '';
  for (let i = 65; i <= 90; i++) {
    const letter = String.fromCharCode(i);
    const btn = document.createElement('button');
    btn.textContent = letter;
    btn.setAttribute('aria-label', `Letter ${letter}`);
    btn.dataset.letter = letter;
    btn.addEventListener('click', () => handleGuess(letter));
    keyboardEl.appendChild(btn);
  }
}

function startGame() {
  currentWord = WORDS[Math.floor(Math.random() * WORDS.length)];
  guessedLetters = new Set();
  wrongCount = 0;
  gameOver = false;
  messageEl.textContent = '';
  messageEl.className = 'message';
  hangmanDrawing.dataset.wrong = '0';
  wrongGuessesDisplay.textContent = `Wrong guesses: 0 / ${MAX_WRONG}`;
  updateWordDisplay();
  updateKeyboard();
}

function updateWordDisplay() {
  wordDisplay.innerHTML = '';
  for (const letter of currentWord) {
    const span = document.createElement('span');
    span.textContent = guessedLetters.has(letter) ? letter : '';
    wordDisplay.appendChild(span);
  }
}

function updateKeyboard() {
  const buttons = keyboardEl.querySelectorAll('button');
  buttons.forEach(btn => {
    btn.disabled = gameOver || guessedLetters.has(btn.dataset.letter);
  });
}

function handleGuess(letter) {
  if (gameOver || guessedLetters.has(letter)) return;
  guessedLetters.add(letter);

  if (currentWord.includes(letter)) {
    updateWordDisplay();
    if (checkWin()) {
      gameOver = true;
      messageEl.textContent = 'You win! 🎉';
      messageEl.className = 'message win';
    }
  } else {
    wrongCount++;
    hangmanDrawing.dataset.wrong = wrongCount;
    wrongGuessesDisplay.textContent = `Wrong guesses: ${wrongCount} / ${MAX_WRONG}`;
    if (wrongCount >= MAX_WRONG) {
      gameOver = true;
      messageEl.textContent = `You lose! The word was ${currentWord}.`;
      messageEl.className = 'message lose';
      revealWord();
    }
  }
  updateKeyboard();
}

function checkWin() {
  return [...currentWord].every(letter => guessedLetters.has(letter));
}

function revealWord() {
  wordDisplay.innerHTML = '';
  for (const letter of currentWord) {
    const span = document.createElement('span');
    span.textContent = letter;
    wordDisplay.appendChild(span);
  }
}

newGameBtn.addEventListener('click', startGame);

initKeyboard();
startGame();
